bounded_host_request.command:
set -eu
python3 - <<'PY'
import subprocess,json
def run(*args):
 p=subprocess.run(args,capture_output=True,text=True,timeout=16)
 return p.returncode,p.stdout.strip()
for name in ("deploy-gaybbs-1","deploy-postgres-1"):
 rc,out=run("docker","inspect",name,"--format","{{json .}}")
 if rc:print(name,"MISSING");continue
 d=json.loads(out)
 print(name,"running="+str(d["State"]["Running"]),"status="+d["State"]["Status"],"exit="+str(d["State"]["ExitCode"]),"image_id="+str(d["Image"])[:23],"restarts="+str(d["RestartCount"]))
 print(name,"compose_service="+d["Config"].get("Labels",{}).get("com.docker.compose.service","UNSET"))
for tag in ("gace-tgtumbler-gaybbs:local","gace-tgtumbler-gaybbs:search-color-5a93de6","gace-tgtumbler-gaybbs:pre-search-color-5a93de6"):
 rc,out=run("docker","image","inspect",tag,"--format","{{.Id}}")
 print("TAG",tag,"ID="+out[:23] if rc==0 else "MISSING")
rc,out=run("docker","compose","ls","--format","json")
if rc==0:
 try:
  for row in json.loads(out):
   if row.get("Name")=="deploy":print("COMPOSE_PROJECT=deploy","STATUS="+str(row.get("Status","UNKNOWN"))[:110])
 except ValueError:print("COMPOSE_LIST_PARSE_FAILED")
PY
